# Build the proposed ray output from the stored test grid g
from collections import defaultdict
src=defaultdict(list)
for r,row in enumerate(g):
    for c in range(1,14):
        if row[c]==0 and row[c-1]!=0 and row[c+1]==row[c-1]: src[c].append((r,row[c-1]))
out=[row[:] for row in g]
for c, ss in src.items():
    prev=-1
    for r,col in ss:
        for rr in range(prev+1,r+1):
            if out[rr][c]==0: out[rr][c]=col
        prev=r
print(dict(src))
print('\n'.join(' '.join(map(str,row)) for row in out))
